fixes.new_str:
function getGreeting(mounted: boolean) {
    if (!mounted) return 'Good evening'
    const hour = new Date().getHours()
    if (hour < 12) return 'Good morning'
    if (hour < 18) return 'Good afternoon'
    return 'Good evening'
  }
